  };

  // vendor/contents/helper.ts
  var exports_helper = {};
  __export(exports_helper, {
    createdInputs: () => createdInputs,
    config: () => config
  });

  // vendor/contents/helper/common.ts
  function waitForElement(selector, timeout = 5000) {
    return new Promise((resolve, reject) => {
      const element = document.querySelector(selector);
      if (element) {
        resolve(element);
        return;
      }
      const observer = new MutationObserver(() => {
        const element2 = document.querySelector(selector);
        if (element2) {
          resolve(element2);
          observer.disconnect();
        }
      });
      observer.observe(document.body, {
        childList: true,
        subtree: true
      });
      setTimeout(() => {
        observer.disconnect();
        reject(new Error(`Element ${selector} not found within ${timeout}ms`));
      }, timeout);
    });
  }

  // vendor/contents/helper/bilibili.ts
  var isProcessingImage = false;
  async function handleBilibiliImageUpload(event) {
    if (isProcessingImage) {
      return;
    }
    isProcessingImage = true;
    const files = event.data.files;
    await waitForElement(".bili-dyn-publishing__image-upload");
    const uploadInput = createdInputs.find((input) => input.type === "file" && input.name === "upload");
    if (!uploadInput) {
      return;
    }
    const dataTransfer = new DataTransfer;
    files.forEach((file) => dataTransfer.items.add(file));
    uploadInput.files = dataTransfer.files;
    const addButton = document.querySelector(".bili-pics-uploader__add");
    uploadInput.disabled = true;
    addButton?.dispatchEvent(new Event("click", { bubbles: true }));
    await new Promise((resolve) => setTimeout(resolve, 1000));
    uploadInput.disabled = false;
    uploadInput.dispatchEvent(new Event("change", { bubbles: true }));
    isProcessingImage = false;
  }

  // vendor/contents/helper/bluesky.ts
  var isProcessingVideo = false;
  async function handleBlueskyVideoUpload(event) {
    if (isProcessingVideo) {
      return;
    }
    isProcessingVideo = true;
    const video = event.data.video;
    if (!video) {
      console.error("未找到视频");
      return;
    }
    const uploadVideoButton = await waitForElement('button[data-testid="openGifBtn"]');
    if (!uploadVideoButton) {
      console.error("未找到上传视频按钮");
      return;
    }
    uploadVideoButton.click();
    await new Promise((resolve) => setTimeout(resolve, 500));
    const uploadInput = createdInputs.find((input) => input.type === "file");
    if (!uploadInput) {
      console.error("未找到上传输入框");
      return;
    }
    const dataTransfer = new DataTransfer;
    dataTransfer.items.add(video);
    uploadInput.files = dataTransfer.files;
    uploadInput.disabled = true;
    await new Promise((resolve) => setTimeout(resolve, 1000));
    uploadInput.disabled = false;
    uploadInput.dispatchEvent(new Event("change", { bubbles: true }));
    isProcessingVideo = false;
  }
  var isProcessingImage2 = false;
  async function handleBlueskyImageUpload(event) {
    if (isProcessingImage2) {
      return;
    }
    isProcessingImage2 = true;
    const images = event.data.images;
    if (!images || images.length === 0) {
      console.error("未找到图片");
      return;
    }
    const uploadButton = await waitForElement('button[data-testid="openGalleryBtn"]');
    if (!uploadButton) {
      console.error("未找到上传按钮");
      return;
    }
    uploadButton.click();
    await new Promise((resolve) => setTimeout(resolve, 500));
    const uploadInput = createdInputs.find((input) => input.type === "file");
    if (!uploadInput) {
      console.error("未找到上传输入框");
      return;
    }
    const dataTransfer = new DataTransfer;
    images.forEach((image) => {
      dataTransfer.items.add(image);
    });
    uploadInput.files = dataTransfer.files;
    uploadInput.disabled = true;
    await new Promise((resolve) => setTimeout(resolve, 1000));
    uploadInput.disabled = false;
    uploadInput.dispatchEvent(new Event("change", { bubbles: true }));
    isProcessingImage2 = false;
  }

  // vendor/contents/helper/jianpian.ts
  var suppressFilePicker = false;
  function prepareJianpianInput(input) {
    if (location.hostname !== "www.jianpian.cn" || !location.pathname.startsWith("/p/edit"))
      return;
    const originalClick = input.click.bind(input);
    input.click = () => {
      if (!suppressFilePicker)
        originalClick();
    };
  }
  async function handleJianpianUpload(event) {
    if (event.source !== window || location.hostname !== "www.jianpian.cn")
      return;
    const files = Array.isArray(event.data.files) ? event.data.files.filter((file) => file instanceof File) : [];
    if (files.length === 0)
      return;
    const importWord = await waitForElement('p[name="导入Word文档"]');
    if (!(importWord instanceof HTMLElement))
      return;
    importWord.click();
    const chooseDocument = await waitForElement('button[name="选择文档"]');
    if (!(chooseDocument instanceof HTMLElement))
      return;
    suppressFilePicker = true;
    chooseDocument.dispatchEvent(new Event("click", { bubbles: true }));
    await new Promise((resolve) => setTimeout(resolve, 500));
    suppressFilePicker = false;
    const input = [...createdInputs].reverse().find((candidate) => candidate.type === "file");
    if (!input)
      return;
    const transfer = new DataTransfer;
    files.forEach((file) => transfer.items.add(file));
    input.files = transfer.files;
    input.dispatchEvent(new Event("change", { bubbles: true }));
    for (let attempt = 0;attempt < 10; attempt += 1) {
      await new Promise((resolve) => setTimeout(resolve, 1000));
      const continueButton = document.querySelector('button[name="继续导入Word"]');
      if (continueButton instanceof HTMLElement) {
        continueButton.click();
        return;
      }
    }
  }

  // vendor/contents/helper/weibo.ts
  var pendingUpload = null;
  function isWeiboVideoPage() {
    return location.hostname === "weibo.com" && location.pathname.startsWith("/upload/channel");
  }
  function postResult(requestId, success, error) {
    window.postMessage({
      type: "WEIBO_UPLOAD_VIDEO_RESULT",
      requestId,
      success,
      error
    }, "*");
  }
  function prepareWeiboVideoInput(input) {
    if (!isWeiboVideoPage())
      return;
    const originalClick = input.click.bind(input);
    input.click = () => {
      const isVideoInput = input.type === "file" && /video|mp4|mov|webm/i.test(input.accept || "");
      if (!isVideoInput || !pendingUpload?.files.length) {
        originalClick();
        return;
      }
      const upload = pendingUpload;
      if (upload.isAssigning)
        return;
      upload.isAssigning = true;
      setTimeout(() => {
        if (pendingUpload !== upload)
          return;
        try {
          const dataTransfer = new DataTransfer;
          upload.files.forEach((file) => dataTransfer.items.add(file));
          input.files = dataTransfer.files;
          if (input.files?.length !== upload.files.length) {
            throw new Error("视频文件未写入上传控件");
          }
          input.dispatchEvent(new Event("change", { bubbles: true }));
          if (pendingUpload === upload)
            pendingUpload = null;
          postResult(upload.requestId, true);
        } catch (error) {
          if (pendingUpload === upload)
            pendingUpload = null;
          const message = error instanceof Error ? error.message : String(error);
          postResult(upload.requestId, false, `视频文件写入失败: ${message}`);
        }
      }, 0);
    };
  }
  async function handleWeiboVideoUpload(event) {
    if (!isWeiboVideoPage())
      return;
    const requestId = typeof event.data.requestId === "string" ? event.data.requestId : undefined;
    const files = Array.isArray(event.data.files) ? event.data.files.filter((file) => file instanceof File && file.type.startsWith("video/")) : [];
    if (files.length === 0) {
      postResult(requestId, false, "没有可上传的视频文件");
      return;
    }
    if (pendingUpload) {
      const replacedUpload = pendingUpload;
      pendingUpload = null;
      postResult(replacedUpload.requestId, false, "新的视频上传请求已替换当前请求");
    }
    const upload = {
      requestId,
      files: files.slice(0, 1),
      isAssigning: false
    };
    pendingUpload = upload;
    try {
      for (let attempt = 0;attempt < 5; attempt++) {
        const uploadButton = document.querySelector("button[id^='video_button_upload_']");
        if (uploadButton) {
          const eventOptions = { bubbles: true, cancelable: true, view: window };
          uploadButton.dispatchEvent(new MouseEvent("mousedown", eventOptions));
          uploadButton.dispatchEvent(new MouseEvent("mouseup", eventOptions));
          uploadButton.dispatchEvent(new MouseEvent("click", eventOptions));
          await new Promise((resolve) => setTimeout(resolve, 500));
          if (pendingUpload !== upload)
            return;
        }
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }
    } catch (error) {
      if (pendingUpload !== upload)
        return;
      pendingUpload = null;
      const message = error instanceof Error ? error.message : String(error);
      postResult(requestId, false, `触发视频上传控件失败: ${message}`);
      return;
    }
    if (pendingUpload === upload) {
      pendingUpload = null;
      postResult(requestId, false, "未能触发微博视频上传控件");
    }
  }

  // vendor/contents/helper/xiaoheihe.ts
  var isProcessingVideo2 = false;
  function getLatestFileInput() {
    for (let index = createdInputs.length - 1;index >= 0; index--) {
      const input = createdInputs[index];
      if (input.type === "file")
        return input;
    }
    return;
  }
  async function handleXiaoheiheVideoUpload(event) {
    if (isProcessingVideo2) {
      return;
    }
    isProcessingVideo2 = true;
    try {
      const video = event.data.video;
      if (!(video instanceof File) || !video.type.startsWith("video/")) {
        console.error("未找到视频");
        return;
      }
      const uploadVideoButton = await waitForElement('button[class="video-uploader__unload"]');
      uploadVideoButton.click();
      await new Promise((resolve) => setTimeout(resolve, 500));
      const uploadInput = getLatestFileInput();
      if (!uploadInput) {
        console.error("未找到上传输入框");
        return;
      }
      const dataTransfer = new DataTransfer;
      dataTransfer.items.add(video);
      uploadInput.files = dataTransfer.files;
      uploadInput.disabled = true;
      await new Promise((resolve) => setTimeout(resolve, 1000));
      uploadInput.disabled = false;
      uploadInput.dispatchEvent(new Event("change", { bubbles: true }));
    } finally {
      isProcessingVideo2 = false;
    }
  }
  var isProcessingImage3 = false;
  async function handleXiaoheiheImageUpload(event) {
    if (isProcessingImage3) {
      return;
    }
    isProcessingImage3 = true;
    try {
      const images = Array.isArray(event.data.images) ? event.data.images.filter((image) => image instanceof File && image.type.startsWith("image/")) : [];
      if (images.length === 0) {
        console.error("未找到图片");
        return;
      }
      const uploadButton = await waitForElement("div.editor-image-wrapper__box.upload, div.upload");
      uploadButton.click();
      await new Promise((resolve) => setTimeout(resolve, 500));
      const uploadInput = getLatestFileInput();
      if (!uploadInput) {
        console.error("未找到上传输入框");
        return;
      }
      const dataTransfer = new DataTransfer;
      images.forEach((image) => dataTransfer.items.add(image));
      uploadInput.files = dataTransfer.files;
      uploadInput.disabled = true;
      await new Promise((resolve) => setTimeout(resolve, 1000));
      uploadInput.disabled = false;
      uploadInput.dispatchEvent(new Event("change", { bubbles: true }));
    } finally {
      isProcessingImage3 = false;
    }
  }

  // vendor/contents/helper.ts
  var config = {
    matches: [
      "https://t.bilibili.com/*",
      "https://bsky.app/*",
      "https://www.v2ex.com/write*",
      "https://v2ex.com/write*",
      "https://www.xiaoheihe.cn/creator/editor/*",
      "https://weibo.com/upload/channel*",
      "https://www.jianpian.cn/p/edit*"
    ],
    world: "MAIN",
    run_at: "document_start"
  };
  var originalCreateElement = document.createElement.bind(document);
  var createdInputs = [];
  document.createElement = (tagName, options) => {
    const element = originalCreateElement(tagName, options);
    if (tagName.toLowerCase() === "input") {
      createdInputs.push(element);
      prepareWeiboVideoInput(element);
      prepareJianpianInput(element);
    }
    return element;
  };
  function handleMessage(event) {
    if (event.source !== window || !event.data || typeof event.data !== "object") {
      return;
    }
    const data = event.data;
    if (data.type === "BILIBILI_DYNAMIC_UPLOAD_IMAGES") {
      handleBilibiliImageUpload(event);
    } else if (data.type === "BLUESKY_VIDEO_UPLOAD") {
      handleBlueskyVideoUpload(event);
    } else if (data.type === "BLUESKY_IMAGE_UPLOAD") {
      handleBlueskyImageUpload(event);
    } else if (data.type === "V2EX_DYNAMIC_UPLOAD") {
      const editor = document.querySelector(".CodeMirror");
      if (editor) {
        editor.CodeMirror.setValue(data.content);
      }
    } else if (data.type === "XIAOHEIHE_IMAGE_UPLOAD") {
      handleXiaoheiheImageUpload(event);
    } else if (data.type === "XIAOHEIHE_VIDEO_UPLOAD") {
      handleXiaoheiheVideoUpload(event);
    } else if (data.type === "WEIBO_UPLOAD_VIDEO") {
      handleWeiboVideoUpload(event);
    } else if (data.type === "JIANPIAN_UPLOAD") {
      handleJianpianUpload(event);
    }
  }
  window.addEventListener("message", handleMessage);
})();

