async function DynamicBilibili(data) {
    function waitForElement(selector, timeout = 10000) {
        return new Promise((resolve, reject) => {
            const exist = document.querySelector(selector);
            if (exist) {
                resolve(exist);
                return;
            }
            const observer = new MutationObserver(() => {
                const found = document.querySelector(selector);
                if (found) {
                    observer.disconnect();
                    resolve(found);
                }
            });
            observer.observe(document.body, { childList: true, subtree: true });
            setTimeout(() => {
                observer.disconnect();
                reject(new Error(`元素 "${selector}" 在 ${timeout}ms 内未出现`));
            }, timeout);
        });
    }
    async function checkImageUploadCompletion(expectedNewCount, initialCount, maxAttempts = 30, interval = 1000) {
        for (let attempt = 0; attempt < maxAttempts; attempt++) {
            const currentSuccessCount = document.querySelectorAll("div.bili-pics-uploader__item.success").length;
            const newlyUploadedCount = currentSuccessCount - initialCount;
            if (newlyUploadedCount === expectedNewCount) {
                console.log(`所有 ${expectedNewCount} 张新图片已成功上传`);
                return;
            }
            await new Promise((resolve) => setTimeout(resolve, interval));
        }
        const finalSuccessCount = document.querySelectorAll("div.bili-pics-uploader__item.success").length;
        console.warn(`图片上传检查超时：预期新增 ${expectedNewCount} 张，实际新增 ${finalSuccessCount - initialCount} 张`);
    }
    async function cleanUploadedImages() {
        for (let i = 0; i < 20; i++) {
            await new Promise((resolve) => setTimeout(resolve, 1000));
            const removeButton = document.querySelector("div.bili-pics-uploader__item__remove");
            if (!removeButton)
                return;
            globalThis.__djlMultiPost.perform(() => removeButton.click());
        }
    }
    try {
        const { content, images, title, tags } = data.data;
        const editor = (await waitForElement('div[placeholder="有什么想和大家分享的？"][contenteditable="true"]'));
        await new Promise((resolve) => setTimeout(resolve, 1000));
        const tagSuffix = tags && tags.length > 0 ? ` ${tags.map((t) => `#${t}#`).join(" ")}` : "";
        const finalContent = `${content || ""}${tagSuffix}`;
        editor.focus();
        editor.textContent = "";
        editor.textContent = finalContent;
        globalThis.__djlMultiPost.perform(() => editor.dispatchEvent(new InputEvent("input", {
            bubbles: true,
            cancelable: true,
            inputType: "insertText",
            data: finalContent,
        })));
        if (title) {
            const titleInput = (await waitForElement('input.bili-dyn-publishing__title__input, input[maxlength="20"][placeholder="好的标题更容易获得支持，选填20字"]'));
            titleInput.focus();
            titleInput.value = title;
            globalThis.__djlMultiPost.perform(() => titleInput.dispatchEvent(new Event("input", { bubbles: true })));
            globalThis.__djlMultiPost.perform(() => titleInput.dispatchEvent(new Event("change", { bubbles: true })));
        }
        const uploadModule = document.querySelector("div.bili-dyn-publishing__image-upload");
        if (uploadModule)
            uploadModule.style.display = "block";
        await cleanUploadedImages();
        if (images && images.length > 0) {
            const imageData = [];
            for (const file of images) {
                const blob = await (await globalThis.__djlMultiPost.fetch(file.url)).blob();
                imageData.push(new File([blob], file.name, { type: file.type || blob.type }));
            }
            await new Promise((resolve) => setTimeout(resolve, 800));
            const initialSuccessCount = document.querySelectorAll("div.bili-pics-uploader__item.success").length;
            window.postMessage({ type: "BILIBILI_DYNAMIC_UPLOAD_IMAGES", files: imageData }, "*");
            await checkImageUploadCompletion(images.length, initialSuccessCount);
        }
        if (data.isAutoPublish)
            globalThis.__djlMultiPost.defer(async () => {
                const maxAttempts = 3;
                for (let attempt = 0; attempt < maxAttempts; attempt++) {
                    const publishButton = document.querySelector("div.bili-dyn-publishing__action.launcher");
                    if (publishButton) {
                        globalThis.__djlMultiPost.perform(() => publishButton.click());
                        await new Promise((resolve) => setTimeout(resolve, 3000));
                        window.location.reload();
                        return;
                    }
                    await new Promise((resolve) => setTimeout(resolve, 1000));
                }
            });
        else {
            const publishButton = (await waitForElement("div.bili-dyn-publishing__action.launcher"));
            publishButton.addEventListener("click", async () => {
                await new Promise((resolve) => setTimeout(resolve, 3000));
                window.location.reload();
            });
        }
    }
    catch (error) {
        console.error("B 站动态发布失败:", error);
    }
}

return DynamicBilibili;

async function DynamicDouyin(data) {
    const { title, content, images, tags } = data.data;
    function waitForElement(selector, timeout = 10000) {
        return new Promise((resolve, reject) => {
            const element = document.querySelector(selector);
            if (element) {
                resolve(element);
                return;
            }
            const observer = new MutationObserver(() => {
                const element = document.querySelector(selector);
                if (element) {
                    resolve(element);
                    observer.disconnect();
                }
            });
            observer.observe(document.body, {
                childList: true,
                subtree: true,
            });
            setTimeout(() => {
                observer.disconnect();
                reject(new Error(`Element with selector "${selector}" not found within ${timeout}ms`));
            }, timeout);
        });
    }
    if (!images || images.length === 0) {
        alert("发布图文，请至少提供一张图片");
        return;
    }
    await waitForElement('input[type="file"]');
    await new Promise((resolve) => setTimeout(resolve, 1000));
    const semiTabs = document.querySelector(".semi-tabs.semi-tabs-top");
    console.debug("semitabs", semiTabs);
    if (!semiTabs || !semiTabs.previousElementSibling) {
        console.error("未找到 semitabs 或其前置元素");
        return;
    }
    const tabsDiv = semiTabs.previousElementSibling.querySelectorAll("div");
    console.debug("tabsDiv", tabsDiv);
    const publishTab = Array.from(tabsDiv).find((e) => e.textContent === "发布图文");
    console.debug("publishTab", publishTab);
    if (!publishTab) {
        console.error("未找到 publishTab");
        return;
    }
    globalThis.__djlMultiPost.perform(() => publishTab.click());
    await new Promise((resolve) => setTimeout(resolve, 1000));
    const fileInput = document.querySelector('input[accept="image/png,image/jpeg,image/jpg,image/bmp,image/webp,image/tif"]');
    console.debug("fileInput", fileInput);
    if (!fileInput) {
        console.error("未找到 fileInput");
        return;
    }
    const dataTransfer = new DataTransfer();
    for (const fileInfo of images) {
        console.debug("try upload file", fileInfo);
        const response = await globalThis.__djlMultiPost.fetch(fileInfo.url);
        const blob = await response.blob();
        const file = new File([blob], fileInfo.name, { type: fileInfo.type });
        dataTransfer.items.add(file);
    }
    fileInput.files = dataTransfer.files;
    const changeEvent = new Event("change", { bubbles: true });
    globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(changeEvent));
    const inputEvent = new Event("input", { bubbles: true });
    globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(inputEvent));
    console.debug("文件上传操作完成");
    await waitForElement('input[placeholder="添加作品标题"]');
    const titleInput = document.querySelector('input[placeholder="添加作品标题"]');
    console.debug("titleInput", titleInput);
    if (titleInput) {
        titleInput.value = title || "";
        globalThis.__djlMultiPost.perform(() => titleInput.dispatchEvent(new Event("input", { bubbles: true })));
    }
    const contentEditor = document.querySelector('div.zone-container.editor-kit-container.editor.editor-comp-publish[contenteditable="true"]');
    if (contentEditor) {
        console.debug("descriptionInput", contentEditor);
        contentEditor.focus();
        const pasteEvent = new ClipboardEvent("paste", {
            bubbles: true,
            cancelable: true,
            clipboardData: new DataTransfer(),
        });
        pasteEvent.clipboardData.setData("text/plain", content || "");
        globalThis.__djlMultiPost.perform(() => contentEditor.dispatchEvent(pasteEvent));
        if (tags?.length) {
            for (const tag of tags.slice(0, 4)) {
                contentEditor.focus();
                const tagPaste = new ClipboardEvent("paste", {
                    bubbles: true,
                    cancelable: true,
                    clipboardData: new DataTransfer(),
                });
                tagPaste.clipboardData?.setData("text/plain", ` #${tag}`);
                globalThis.__djlMultiPost.perform(() => contentEditor.dispatchEvent(tagPaste));
                await new Promise((resolve) => setTimeout(resolve, 600));
            }
        }
    }
    await new Promise((resolve) => setTimeout(resolve, 5000));
    if (data.isAutoPublish)
        globalThis.__djlMultiPost.defer(async () => {
            const buttons = document.querySelectorAll("button");
            const publishButton = Array.from(buttons).find((e) => e.textContent === "发布");
            if (publishButton) {
                console.debug("sendButton clicked");
                globalThis.__djlMultiPost.perform(() => publishButton.click());
                await new Promise((resolve) => setTimeout(resolve, 10000));
                window.location.href = "https://creator.douyin.com/creator-micro/content/manage";
            }
            else {
                console.debug("未找到'发布'按钮");
            }
        });
}

return DynamicDouyin;

async function DynamicX(data) {
    const { title, content, images, videos, tags } = data.data;
    function waitForElement(selector, timeout = 10000) {
