async function DynamicXueqiu(data) {
    const { title, content, images, videos, tags } = data.data;
    function waitForElement(selector, timeout = 10000) {
        return new Promise((resolve, reject) => {
            const element = document.querySelector(selector);
            if (element) {
                resolve(element);
                return;
            }
            const observer = new MutationObserver(() => {
                const element = document.querySelector(selector);
                if (element) {
                    resolve(element);
                    observer.disconnect();
                }
            });
            observer.observe(document.body, {
                childList: true,
                subtree: true,
            });
            setTimeout(() => {
                observer.disconnect();
                reject(new Error(`Element with selector "${selector}" not found within ${timeout}ms`));
            }, timeout);
        });
    }
    async function waitForElementOptional(selector, timeout = 10000) {
        return waitForElement(selector, timeout).catch(() => null);
    }
    async function getUploadFileInput() {
        const formSelector = 'form[target="uploadFrame"]';
        const inputSelector = 'input[type="file"]';
        const scopedSelector = `${formSelector} ${inputSelector}`;
        const existingForm = document.querySelector(formSelector);
        if (existingForm) {
            return (existingForm.querySelector(inputSelector) ||
                (await waitForElementOptional(scopedSelector, 3000)));
        }
        const scopedInput = (await waitForElementOptional(scopedSelector, 3000));
        const form = document.querySelector(formSelector);
        if (form) {
            return scopedInput || form.querySelector(inputSelector);
        }
        return (document.querySelector(inputSelector) ||
            (await waitForElementOptional(inputSelector, 3000)));
    }
    async function uploadFiles(files) {
        if (files.length === 0)
            return false;
        const fileInput = await getUploadFileInput();
        if (!fileInput) {
            console.error("media requested but upload input not found");
            return false;
        }
        const dataTransfer = new DataTransfer();
        for (const file of files) {
            dataTransfer.items.add(file);
        }
        fileInput.files = dataTransfer.files;
        globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(new Event("change", { bubbles: true })));
        globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(new Event("input", { bubbles: true })));
        await new Promise((resolve) => setTimeout(resolve, 2000));
        console.debug("文件上传操作完成");
        return true;
    }
    function isImageFileData(file) {
        const mime = (file.type || "").toLowerCase();
        if (mime.startsWith("image/"))
            return true;
        if (mime.startsWith("video/") || mime === "application/pdf")
            return false;
        const hasCommonImageExtension = /\.(gif|jpe?g|png|webp)$/i.test(file.name);
        return (!mime || mime === "application/octet-stream") && hasCommonImageExtension;
    }
    function waitForElements(selector, count, timeout = 30000) {
        return new Promise((resolve, reject) => {
            const checkElements = () => {
                const elements = document.querySelectorAll(selector);
                if (elements.length >= count) {
                    resolve(Array.from(elements));
                    return;
                }
                if (Date.now() - startTime > timeout) {
                    reject(new Error(`未能在 ${timeout}ms 内找到 ${count} 个 "${selector}" 元素`));
                    return;
                }
                setTimeout(checkElements, 100);
            };
            const startTime = Date.now();
            checkElements();
        });
    }
    try {
        const placeholder = (await waitForElement('div[class="fake-placeholder"]'));
        globalThis.__djlMultiPost.perform(() => placeholder.click());
        await new Promise((resolve) => setTimeout(resolve, 1000));
        const inputElement = (await waitForElement('div[class="medium-editor-element"][contenteditable="true"]'));
        const tagSuffix = tags?.length ? ` ${tags.map((t) => `$${t}`).join(" ")}` : "";
        const fullContent = `${title}\n${content}${tagSuffix}`;
        const pasteEvent = new ClipboardEvent("paste", {
            bubbles: true,
            cancelable: true,
            clipboardData: new DataTransfer(),
        });
        pasteEvent.clipboardData.setData("text/plain", fullContent);
        inputElement.focus();
        globalThis.__djlMultiPost.perform(() => inputElement.dispatchEvent(pasteEvent));
        console.debug("成功填入雪球内容");
        const requestedMediaCount = (images?.length ?? 0) + (videos?.length ?? 0);
        let attachedMediaCount = 0;
        if (images && images.length > 0) {
            const imageFiles = [];
            for (const file of images) {
                if (!isImageFileData(file)) {
                    console.debug("跳过非图片文件:", file);
                    continue;
                }
                try {
                    const response = await globalThis.__djlMultiPost.fetch(file.url);
                    if (!response.ok) {
                        throw new Error(`Failed to fetch image "${file.name}": ${response.status} ${response.statusText}`);
                    }
                    const blob = await response.blob();
                    const fileType = file.type || blob.type;
                    if (!isImageFileData({ ...file, type: fileType })) {
                        console.debug("跳过非图片文件:", file);
                        continue;
                    }
                    imageFiles.push(new File([blob], file.name, { type: fileType }));
                }
                catch (error) {
                    console.error("获取图片失败:", error);
                }
            }
            if (imageFiles.length > 0) {
                const currentUploaded = document.querySelectorAll(".img-single-upload");
                const uploaded = await uploadFiles(imageFiles);
                if (uploaded) {
                    try {
                        await waitForElements(".img-single-upload", imageFiles.length + currentUploaded.length);
                        attachedMediaCount = imageFiles.length;
                    }
                    catch (error) {
                        const uploadedCount = document.querySelectorAll(".img-single-upload").length - currentUploaded.length;
                        attachedMediaCount = Math.max(0, Math.min(imageFiles.length, uploadedCount));
                        console.error("image upload confirmation failed:", error);
                    }
                }
            }
        }
        console.debug("成功填入雪球内容和图片");
        await new Promise((resolve) => setTimeout(resolve, 5000));
        globalThis.__djlMultiPost.defer(async () => {
            if (data.isAutoPublish && requestedMediaCount > 0 && attachedMediaCount !== requestedMediaCount) {
                console.error(`only ${attachedMediaCount} of ${requestedMediaCount} requested media attached; skipping auto-publish to avoid an incomplete post`);
                return;
            }
            if (data.isAutoPublish) {
                const maxAttempts = 3;
                for (let attempt = 0; attempt < maxAttempts; attempt++) {
                    try {
                        const sendButton = (await waitForElement('a[class="lite-editor__submit"]', 5000));
                        globalThis.__djlMultiPost.perform(() => sendButton.click());
                        console.log("发送按钮已点击");
                        await new Promise((resolve) => setTimeout(resolve, 3000));
                        window.location.reload();
                        break;
                    }
                    catch (error) {
                        console.warn(`第 ${attempt + 1} 次尝试查找发送按钮失败:`, error);
                        if (attempt === maxAttempts - 1) {
                            console.error("达到最大尝试次数，无法找到发送按钮");
                        }
                        await new Promise((resolve) => setTimeout(resolve, 2000));
                    }
                }
            }
        });
    }
    catch (error) {
        console.error("填入雪球内容或上传图片时出错:", error);
    }
}

