            function findElementInRoot(root) {
                const element = root.querySelector(selector);
                if (element)
                    return element;
                const allElements = root.querySelectorAll("*");
                for (const el of allElements) {
                    if (el.shadowRoot) {
                        const found = findElementInRoot(el.shadowRoot);
                        if (found)
                            return found;
                    }
                }
                return null;
            }
