                    if (element) {
                        return element;
                    }
                    return findElementInRoot(wujieApp.shadowRoot);
                }
                return findElementInRoot(document);
            }
            const element = findInWujieApp();
            if (element) {
                resolve(element);
                return;
            }
            const observer = new MutationObserver(() => {
                const element = findInWujieApp();
