            const intervalCheck = setInterval(() => {
                const element = findInWujieApp();
                if (element) {
                    resolve(element);
                    observer.disconnect();
                    clearInterval(intervalCheck);
                }
            }, 1000);
            setTimeout(() => {
                observer.disconnect();
                clearInterval(intervalCheck);
                reject(new Error(`Element with selector "${selector}" not found within ${timeout}ms`));
            }, timeout);
        });
