async function ArticleSSPai(data) {
    console.debug("ArticleSSPai", data);
    function waitForElement(selector, timeout = 10000) {
        return new Promise((resolve, reject) => {
            const element = document.querySelector(selector);
            if (element) {
                resolve(element);
                return;
            }
            const observer = new MutationObserver(() => {
                const element = document.querySelector(selector);
                if (element) {
                    resolve(element);
                    observer.disconnect();
                }
            });
            observer.observe(document.body, {
                childList: true,
                subtree: true,
            });
            setTimeout(() => {
                observer.disconnect();
                reject(new Error(`Element with selector "${selector}" not found within ${timeout}ms`));
            }, timeout);
        });
    }
    async function findElementByText(selector, text, maxRetries = 5, retryInterval = 1000) {
        for (let i = 0; i < maxRetries; i++) {
            const elements = document.querySelectorAll(selector);
            const element = Array.from(elements).find((element) => element.textContent?.includes(text));
            if (element) {
                return element;
            }
            console.log(`未找到包含文本 "${text}" 的元素，尝试次数：${i + 1}`);
            await new Promise((resolve) => setTimeout(resolve, retryInterval));
        }
        console.error(`在 ${maxRetries} 次尝试后未找到包含文本 "${text}" 的元素`);
        return null;
    }
    const articleData = data.origin;
    async function uploadCoverImage() {
        if (!articleData.cover) {
            console.debug("没有封面图片需要上传");
            return true;
        }
        try {
            const fileInput = document.querySelector('input[type="file"]');
            if (!fileInput) {
                console.debug("未找到文件上传输入框");
                return false;
            }
            const dataTransfer = new DataTransfer();
            const coverImage = articleData.cover;
            console.debug("开始上传文件", coverImage);
            const response = await globalThis.__djlMultiPost.fetch(coverImage.url);
            const arrayBuffer = await response.arrayBuffer();
            const file = new File([arrayBuffer], coverImage.name, { type: coverImage.type });
            dataTransfer.items.add(file);
            console.debug("文件已准备");
            if (dataTransfer.files.length > 0) {
                fileInput.files = dataTransfer.files;
                const changeEvent = new Event("change", { bubbles: true });
                globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(changeEvent));
                console.debug("文件上传操作完成");
            }
            await new Promise((resolve) => setTimeout(resolve, 5000));
            const cutAndUseButtonSpan = await findElementByText("span", "裁切并使用");
            if (cutAndUseButtonSpan) {
                const cutAndUseButton = cutAndUseButtonSpan.parentElement;
                if (cutAndUseButton) {
                    const clickEvent = new Event("click", { bubbles: true });
                    globalThis.__djlMultiPost.perform(() => cutAndUseButton.dispatchEvent(clickEvent));
                }
            }
            return true;
        }
        catch (error) {
            console.error("上传封面图片失败:", error);
            return false;
        }
    }
    async function fillArticleContent() {
        const titleTextarea = (await waitForElement('textarea[placeholder="请输入标题..."]'));
        await new Promise((resolve) => setTimeout(resolve, 1000));
        titleTextarea.value = articleData.title?.slice(0, 100) || "";
        globalThis.__djlMultiPost.perform(() => titleTextarea.dispatchEvent(new Event("input", { bubbles: true })));
        globalThis.__djlMultiPost.perform(() => titleTextarea.dispatchEvent(new Event("change", { bubbles: true })));
        console.debug("titleTextarea", titleTextarea, titleTextarea.value);
        const editorDiv = (await waitForElement('div[contenteditable="true"]'));
        if (!editorDiv) {
            console.debug("未找到编辑器元素");
            return false;
        }
        const editor = editorDiv.querySelector("p");
        if (!editor) {
            console.debug("未找到编辑器元素");
            return false;
        }
        editor.focus();
        const pasteEvent = new ClipboardEvent("paste", {
            bubbles: true,
            cancelable: true,
            clipboardData: new DataTransfer(),
        });
        pasteEvent.clipboardData.setData("text/plain", articleData.markdownContent || "");
        globalThis.__djlMultiPost.perform(() => editor.dispatchEvent(pasteEvent));
        globalThis.__djlMultiPost.perform(() => editor.dispatchEvent(new Event("input", { bubbles: true })));
        globalThis.__djlMultiPost.perform(() => editor.dispatchEvent(new Event("change", { bubbles: true })));
        await new Promise((resolve) => setTimeout(resolve, 3000));
        const convertButtonSpan = await findElementByText("span", "立即转换");
        if (convertButtonSpan) {
            const convertButton = convertButtonSpan.parentElement;
            if (convertButton) {
                const clickEvent = new Event("click", { bubbles: true });
                globalThis.__djlMultiPost.perform(() => convertButton.dispatchEvent(clickEvent));
            }
        }
        return true;
    }
    async function publishArticle() {
        if (data.isAutoPublish)
            globalThis.__djlMultiPost.defer(async () => {
                const publishButton = await findElementByText("button", "发布");
                if (publishButton) {
                    const clickEvent = new Event("click", { bubbles: true });
                    globalThis.__djlMultiPost.perform(() => publishButton.dispatchEvent(clickEvent));
                }
                return;
            });
        const previewButton = document.querySelector("a.editor-extra-button-preview") || (await findElementByText("button", "预览"));
        console.debug("previewButton", previewButton);
        if (previewButton) {
            console.debug("previewButton clicked");
            const clickEvent = new Event("click", { bubbles: true });
            globalThis.__djlMultiPost.perform(() => previewButton.dispatchEvent(clickEvent));
        }
        else {
            console.debug('未找到"预览"按钮');
        }
    }
    try {
        await uploadCoverImage();
        const contentFilled = await fillArticleContent();
        if (!contentFilled) {
            throw new Error("填充文章内容失败");
        }
        await publishArticle();
    }
    catch (error) {
        console.error("发布文章失败:", error);
    }
}

