async function ArticleDaYuHao(data) {
    const articleData = data.data;
    function sleep(ms) {
        return new Promise((resolve) => setTimeout(resolve, ms));
    }
    function waitForElementOptional(selector, timeout = 15000) {
        return new Promise((resolve) => {
            const element = document.querySelector(selector);
            if (element) {
                resolve(element);
                return;
            }
            const root = document.body || document.documentElement;
            if (!root) {
                resolve(null);
                return;
            }
            const observer = new MutationObserver(() => {
                const found = document.querySelector(selector);
                if (found) {
                    observer.disconnect();
                    window.clearTimeout(timeoutId);
                    resolve(found);
                }
            });
            const timeoutId = window.setTimeout(() => {
                observer.disconnect();
                resolve(null);
            }, timeout);
            observer.observe(root, { childList: true, subtree: true });
        });
    }
    function dispatchInputEvents(element) {
        globalThis.__djlMultiPost.perform(() => element.dispatchEvent(new Event("input", { bubbles: true })));
        globalThis.__djlMultiPost.perform(() => element.dispatchEvent(new Event("change", { bubbles: true })));
    }
    function setControlValue(element, value) {
        const prototype = element instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
        const valueSetter = Object.getOwnPropertyDescriptor(prototype, "value")?.set;
        if (valueSetter) {
            valueSetter.call(element, value);
        }
        else {
            element.value = value;
        }
        dispatchInputEvents(element);
    }
    function getIframeEditorBody() {
        const iframe = document.getElementById("ueditor_0");
        if (!iframe)
            return null;
        try {
            return iframe.contentDocument?.body || iframe.contentWindow?.document.body || null;
        }
        catch (error) {
            console.debug("Dayuhao iframe editor is not accessible:", error);
            return null;
        }
    }
    function waitForIframeBodyOptional(timeout = 15000) {
        return new Promise((resolve) => {
            const deadline = Date.now() + timeout;
            const check = () => {
                const body = getIframeEditorBody();
                if (body) {
                    resolve(body);
                    return;
                }
                if (Date.now() >= deadline) {
                    resolve(null);
                    return;
                }
                window.setTimeout(check, 250);
            };
            check();
        });
    }
    function writeHtml(editor, html) {
        editor.focus();
        editor.innerHTML = html;
        dispatchInputEvents(editor);
    }
    function canAutoPublish(required) {
