            async performCoverUpload(fileInput, coverUrl) {
                try {
                    const response = await globalThis.__djlMultiPost.fetch(coverUrl);
                    const blob = await response.blob();
                    const fileName = `cover_${Date.now()}.${blob.type.split("/")[1] || "jpg"}`;
                    const coverFile = new File([blob], fileName, { type: blob.type });
                    console.log("📄 封面文件信息:", {
                        name: coverFile.name,
                        type: coverFile.type,
                        size: coverFile.size,
                    });
                    if (!coverFile.type.startsWith("image/")) {
                        console.log("⚠️ 文件类型不是图片:", coverFile.type);
                    }
                    const dataTransfer = new DataTransfer();
                    dataTransfer.items.add(coverFile);
                    fileInput.files = dataTransfer.files;
                    globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(new Event("change", { bubbles: true })));
                    globalThis.__djlMultiPost.perform(() => fileInput.dispatchEvent(new Event("input", { bubbles: true })));
