    async function waitForElement(selector, timeout = 15000) {
        const deadline = Date.now() + timeout;
        while (Date.now() < deadline) {
            const element = document.querySelector(selector);
            if (element)
                return element;
            await sleep(250);
        }
        return null;
    }
    function setTextInput(element, value) {
        if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
            element.value = value;
            globalThis.__djlMultiPost.perform(() => element.dispatchEvent(new Event("input", { bubbles: true })));
            globalThis.__djlMultiPost.perform(() => element.dispatchEvent(new Event("change", { bubbles: true })));
            return true;
        }
        if (element instanceof HTMLElement && element.isContentEditable) {
            element.innerText = value;
            globalThis.__djlMultiPost.perform(() => element.dispatchEvent(new Event("input", { bubbles: true })));
            return true;
        }
        return false;
    }
    async function fileFromUrl(file) {
        const response = await globalThis.__djlMultiPost.fetch(file.url);
        if (!response.ok) {
            console.error(`搜狐视频素材读取失败：HTTP ${response.status}`);
            return null;
        }
        const blob = await response.blob();
        return new File([blob], file.name, { type: file.type || blob.type || "application/octet-stream" });
    }
    async function dispatchFile(input, file) {
        const transfer = new DataTransfer();
        transfer.items.add(file);
        if (transfer.files.length === 0)
            return false;
        input.files = transfer.files;
        globalThis.__djlMultiPost.perform(() => input.dispatchEvent(new Event("change", { bubbles: true })));
        globalThis.__djlMultiPost.perform(() => input.dispatchEvent(new Event("input", { bubbles: true })));
        return true;
    }
    async function uploadVideo() {
        if (!videoData.video)
            return false;
        const element = await waitForElement('input[type="file"]');
        if (!(element instanceof HTMLInputElement))
            return false;
        const file = await fileFromUrl(videoData.video);
        return file ? dispatchFile(element, file) : false;
    }
    async function uploadCover() {
        const cover = videoData.horizontalCover || videoData.cover;
        if (!cover)
            return;
        const trigger = await waitForElement("p.pic-edit", 5000);
        if (!(trigger instanceof HTMLElement))
            return;
        globalThis.__djlMultiPost.perform(() => trigger.click());
        const input = await waitForElement("input.uploadImg", 5000);
        if (!(input instanceof HTMLInputElement))
            return;
        const file = await fileFromUrl(cover);
